1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	    }
28	    [data-color="red"] { --fg: #dc2626; }
29	    [data-color="green"] { --fg: #16a34a; }
30	    [data-color="amber"] { --fg: #d97706; }
31	    [data-color="violet"] { --fg: #7c3aed; }
32	    [data-color="cyan"] { --fg: #0891b2; }
33	    @media (prefers-color-scheme: dark) {
34	      :root {
35	        --bg: #111;
36	        --text: #d1d5db;
37	        --fg: #93c5fd;
38	        --shadow: rgba(0, 0, 0, 0.6);
39	        --kbd-bg: rgba(255, 255, 255, 0.15);
40	      }
41	      [data-color="red"] { --fg: #fca5a5; }
42	      [data-color="green"] { --fg: #86efac; }
43	      [data-color="amber"] { --fg: #fcd34d; }
44	      [data-color="violet"] { --fg: #c4b5fd; }
45	      [data-color="cyan"] { --fg: #67e8f9; }
46	    }
47	    @media (prefers-contrast: more) {
48	      :root {
49	        --shadow: rgba(0, 0, 0, 0.9);
50	      }
51	      .hint {
52	        opacity: 1;
53	      }
54	    }
55	    @media (forced-colors: active) {
56	      svg circle {
57	        stroke: CanvasText;
58	        stroke-width: 2;
59	      }
60	    }
61	    body {
62	      min-height: 100vh;
63	      min-height: 100dvh;
64	      display: grid;
65	      place-items: center;
66	      padding: 1rem;
67	      background: var(--bg);
68	      color: var(--text);
69	      font-family: system-ui, -apple-system, sans-serif;
70	    }
71	    main {
72	      width: 100%;
73	      display: flex;
74	      flex-direction: column;
75	      align-items: center;
76	      text-align: center;
77	    }
78	    button {
79	      display: block;
80	      width: min(360px, 100%, 60vh);
81	      aspect-ratio: 1;
82	      border: 0;
83	      border-radius: 50%;
84	      background: none;
85	      color: var(--fg);
86	      cursor: pointer;
87	      touch-action: manipulation;
88	      -webkit-tap-highlight-color: transparent;
89	      transition: color 0.4s ease;
90	    }
91	    .no-transition,
92	    .no-transition svg {
93	      transition: none !important;
94	    }
95	    button:focus-visible {
96	      outline: 3px solid var(--fg);
97	      outline-offset: 8px;
98	    }
99	    svg {
100	      display: block;
101	      width: 100%;
102	      height: 100%;
103	      overflow: visible;
104	      opacity: 0.9;
105	      filter: drop-shadow(0 8px 16px var(--shadow));
106	      transition: opacity 0.3s ease;
107	    }
108	    button:active svg,
109	    button:focus-visible svg {
110	      opacity: 1;
111	    }
112	    @keyframes pulse {
113	      0% {
114	        filter: drop-shadow(0 8px 16px var(--shadow)) drop-shadow(0 0 20px var(--fg));
115	      }
116	      100% {
117	        filter: drop-shadow(0 8px 16px var(--shadow));
118	      }
119	    }
120	    @media (hover: hover) {
121	      button:hover svg {
122	        opacity: 1;
123	      }
124	    }
125	    @media (prefers-reduced-motion: no-preference) {
126	      svg {
127	        transition:
128	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
129	          opacity 0.3s ease;
130	      }
131	      button:focus-visible svg {
132	        transform: scale(1.05);
133	      }
134	      button:active svg {
135	        transform: scale(0.97);
136	      }
137	      button.color-changed svg {
138	        animation: pulse 0.5s ease-out;
139	      }
140	    }
141	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
142	      button:hover:not(:active) svg {
143	        transform: scale(1.05);
144	      }
145	    }
146	    .status {
147	      margin-top: 2rem;
148	      font-weight: 600;
149	    }
150	    .hint {
151	      margin-top: 0.25rem;
152	      font-size: 0.875rem;
153	      opacity: 0.8;
154	    }
155	    kbd {
156	      display: inline-block;
157	      padding: 0.125rem 0.375rem;
158	      background: var(--kbd-bg);
159	      border: 1px solid transparent;
160	      border-radius: 0.25rem;
161	      font-family: monospace;
162	      font-size: 0.75em;
163	    }
164	  </style>
165	</head>
166	<body>
167	  <main>
168	    <button type="button" class="no-transition" aria-label="Change circle color" aria-describedby="status hint">
169	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
170	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
171	      </svg>
172	    </button>
173	    <p class="status" id="status" role="status">Blue</p>
174	    <p class="hint" id="hint"><span class="verb">Click</span> to change color (or press <kbd>Space</kbd> or <kbd>Enter</kbd>; hold <kbd>Shift</kbd> to go back)</p>
175	  </main>
176	  <script>
177	    const button = document.querySelector('button');
178	    const status = document.querySelector('.status');
179	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
180	    const storageKey = 'circle-color';
181	
182	    function loadColor() {
183	      try {
184	        return localStorage.getItem(storageKey);
185	      } catch {
186	        return null;
187	      }
188	    }
189	
190	    function saveColor(color) {
191	      try {
192	        localStorage.setItem(storageKey, color);
193	      } catch {}
194	    }
195	
196	    const savedColor = loadColor();
197	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
198	
199	    function applyColor() {
200	      const color = colors[index];
201	      if (color === 'blue') {
202	        delete button.dataset.color;
203	      } else {
204	        button.dataset.color = color;
205	      }
206	      status.textContent = color[0].toUpperCase() + color.slice(1);
207	    }
208	
209	    function changeColor(event) {
210	      const step = event.shiftKey ? -1 : 1;
211	      index = (index + step + colors.length) % colors.length;
212	      applyColor();
213	      saveColor(colors[index]);
214	
215	      button.classList.remove('color-changed');
216	      void button.offsetWidth;
217	      button.classList.add('color-changed');
218	    }
219	
220	    applyColor();
221	    requestAnimationFrame(() => {
222	      requestAnimationFrame(() => button.classList.remove('no-transition'));
223	    });
224	
225	    if (matchMedia('(hover: none)').matches) {
226	      document.querySelector('.hint .verb').textContent = 'Tap';
227	    }
228	
229	    button.addEventListener('click', changeColor);
230	    button.addEventListener('animationend', () => {
231	      button.classList.remove('color-changed');
232	    });
233	  </script>
234	</body>
235	</html>
